__device__ __forceinline__ float block_reduce_sum(float value) {
    __shared__ float warp_sums[32];

    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;

    for (int offset = 16; offset > 0; offset >>= 1) {
        value += __shfl_down_sync(0xffffffff, value, offset);
    }

    if (lane == 0) {
        warp_sums[warp] = value;
    }

    __syncthreads();

    const int warp_count = (blockDim.x + 31) >> 5;
    value = (threadIdx.x < warp_count) ? warp_sums[threadIdx.x] : 0.0f;

    if (warp == 0) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            value += __shfl_down_sync(0xffffffff, value, offset);
        }
        if (lane == 0) {
            warp_sums[0] = value;
        }
    }

    __syncthreads();
    return warp_sums[0];
}

__global__ void layer_norm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int64_t rows,
    int64_t normalized_size,
    float eps) {
    for (int64_t row = static_cast<int64_t>(blockIdx.x);
         row < rows;
         row += static_cast<int64_t>(gridDim.x)) {
        const int64_t base = row * normalized_size;

        float sum = 0.0f;
        if ((normalized_size & 3) == 0) {
            const float4* input4 = reinterpret_cast<const float4*>(input + base);
            const int64_t normalized_vec4 = normalized_size >> 2;
            for (int64_t i = threadIdx.x; i < normalized_vec4; i += blockDim.x) {
                const float4 value = input4[i];
                sum += value.x + value.y + value.z + value.w;
            }
        } else {
            for (int64_t i = threadIdx.x; i < normalized_size; i += blockDim.x) {
                sum += input[base + i];
            }
        }
        sum = block_reduce_sum(sum);
        const float mean = sum / static_cast<float>(normalized_size);
        float variance_sum = 0.0f;
        if ((normalized_size & 3) == 0) {
            const float4* input4 = reinterpret_cast<const float4*>(input + base);
            const int64_t normalized_vec4 = normalized_size >> 2;
            for (int64_t i = threadIdx.x; i < normalized_vec4; i += blockDim.x) {
                const float4 value = input4[i];
                const float centered_x = value.x - mean;
                const float centered_y = value.y - mean;
                const float centered_z = value.z - mean;
                const float centered_w = value.w - mean;
                variance_sum += centered_x * centered_x + centered_y * centered_y +
                                centered_z * centered_z + centered_w * centered_w;
            }
        } else {
            for (int64_t i = threadIdx.x; i < normalized_size; i += blockDim.x) {
                const float centered = input[base + i] - mean;
                variance_sum += centered * centered;
            }
        }
        variance_sum = block_reduce_sum(variance_sum);
        const float variance = variance_sum / static_cast<float>(normalized_size);
        const float inv_std = rsqrtf(variance + eps);
        if ((normalized_size & 3) == 0) {
            const float4* input4 = reinterpret_cast<const float4*>(input + base);
            const float4* weight4 = reinterpret_cast<const float4*>(weight);
            const float4* bias4 = reinterpret_cast<const float4*>(bias);
            float4* output4 = reinterpret_cast<float4*>(output + base);
            const int64_t normalized_vec4 = normalized_size >> 2;
            for (int64_t i = threadIdx.x; i < normalized_vec4; i += blockDim.x) {
                const float4 value = input4[i];
                const float4 scale = weight4[i];
                const float4 shift = bias4[i];
                output4[i] = make_float4(
                    (value.x - mean) * inv_std * scale.x + shift.x,
                    (value.y - mean) * inv_std * scale.y + shift.y,
                    (value.z - mean) * inv_std * scale.z + shift.z,
                    (value.w - mean) * inv_std * scale.w + shift.w);
            }
        } else {
            for (int64_t i = threadIdx.x; i < normalized_size; i += blockDim.x) {
                const float normalized = (input[base + i] - mean) * inv_std;
                output[base + i] = normalized * weight[i] + bias[i];
            }
        }
    }
}

